import{z as A,x as E,o as n,c as D,q as s,j as i,D as r,d as t,s as N,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"与或非与万能门","description":"","frontmatter":{"title":"与或非与万能门","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nand-universal.md","filePath":"cs/nand-universal.md","lastUpdated":1791413859000}'),d={name:"cs/nand-universal.md"};function p(B,a,m,O,h,u){const l=E("Mermaid");return n(),D("div",null,[a[2]||(a[2]=s('<h1 id="与或非与万能门" tabindex="-1">与或非与万能门 <a class="header-anchor" href="#与或非与万能门" aria-label="Permalink to &quot;与或非与万能门&quot;">​</a></h1><div class="epigraph"><p>与非单独就能拼出与、或、非；因此一片只烧与非的阵列在功能上已经完备。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Shannon, 1938 整理</footer></div><p>上一课<a href="/cs/cmos-inverter">CMOS 反相器</a>钉死了非的硅实现。本课不重画转移曲线，也不从布尔公理再证一遍交换律。<a href="/cs/boolean-algebra">布尔代数</a>已有与或非；缺口是：<strong>哪些门集合能实现全部布尔函数</strong>，以及 CMOS 上与非为何是自然的万能门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反相器只有一输入。任意 \\(n\\) 元函数需要能表达与、或、非中的全体——布尔课已证三者完备。缺口是实现：CMOS 把串联 nMOS、并联 pMOS 做成与非，对偶做成或非，比「与再加非」少一级。NAND（或 NOR）单独完备：\\(\\bar x = x\\,\\mathrm{NAND}\\,x\\)，与、或由此拼出。</p><p><span class="marginnote">术语翻译：「功能完备」就是一套门能拼出全部布尔函数，不多不少。全用 NAND 拼三种基本门的口诀只有三句——非：两端接同一个输入；与：先 NAND 一次再自反一次；或：把两个输入各自先取反，再做 NAND（这正是 De Morgan 律搬到器件上）。</span></p><p>本课只钉功能完备与 CMOS 复合物。延迟、负载在后面的<a href="/cs/gate-delay">组合逻辑时延</a>一课展开。AOI 复合门点到为止。</p><h3 id="万能不是「延迟最短」" tabindex="-1">万能不是「延迟最短」 <a class="header-anchor" href="#万能不是「延迟最短」" aria-label="Permalink to &quot;万能不是「延迟最短」&quot;">​</a></h3><p>NAND 万能指功能，不指时序最优。全用 NAND 的网表往往更深。后课综合会混用。把「FPGA 基本单元」提前成 NAND 也不对：LUT 是另一层，本课不讲可编程结构。</p><p><span class="marginnote">Harris 给出 CMOS NAND/NOR 的管级串联并联。De Morgan 在器件上就是把气泡挪到另一边。本课不把晶体管尺寸比写成模拟作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CMOS NAND2：两个 nMOS 串联接地，两个 pMOS 并联上拉。输出低仅当两输入都高。NOR 对偶。用 NAND 构造 NOT、AND、OR 的等式按布尔课改写，不再列公理。</p>',12)),(n(),i(o,null,{default:r(()=>[N(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22CMOS%20%E9%9D%9E%22%5D%20--%3E%20NAND%5B%22CMOS%20%E4%B8%8E%E9%9D%9E%22%5D%0A%20%20NAND%20--%3E%20UNIV%5B%22%7BNAND%7D%20%E5%8A%9F%E8%83%BD%E5%AE%8C%E5%A4%87%22%5D%0A%20%20UNIV%20--%3E%20NET%5B%22%E4%BB%BB%E6%84%8F%E7%BB%84%E5%90%88%E7%BD%91%E8%A1%A8%22%5D%0A%20%20NET%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了万能门，任意规范 SOP 都能映射成门网：与项用 NAND-NAND 或 AND-OR。PLA、标准单元库以 NAND/NOR/AOI 为砖。纠错码的异或是与或非的组合，本课不把门级 XOR 展开成晶体管数竞赛。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：用与非拼二输入与门要 2 个门、6 只晶体管（NAND 4 管 + 反相器 2 管），比直接做与门还多——那为什么工厂偏爱 NAND？因为它的 CMOS 结构最自然（nMOS 串联、pMOS 并联），且单一门种就能实现一切电路，单元库与流水线都更简单。")],-1)),a[6]||(a[6]=e("p",null,"扇入增大则串联堆叠变慢、噪声容限变差，这是延迟课的入口；本课只承认堆叠合法。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者把「万能」理解成「最快」或「最省」。全 NAND 的网表逻辑级数往往更深、延迟更大，实际综合器会混用门；「功能完备」也不等于「图灵完备」——这里没有状态、没有存储，只谈组合函数能不能拼出来。")],-1)),(n(),i(o,null,{default:r(()=>[N(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22%E8%BE%93%E5%85%A5%20x%2C%20y%22%5D%20--%3E%20NOT%5B%22%E9%9D%9E%EF%BC%9ANAND(x%2C%20x)%22%5D%0A%20%20XY%20--%3E%20S1%5B%22NAND(x%2C%20y)%22%5D%0A%20%20S1%20--%3E%20AND%5B%22%E4%B8%8E%EF%BC%9A%E5%86%8D%20NAND%20%E8%87%AA%E5%8F%8D%E4%B8%80%E6%AC%A1%22%5D%0A%20%20XY%20--%3E%20IX%5B%22NAND(x%2C%20x)%20%E5%BE%97%20%E9%9D%9Ex%22%5D%0A%20%20XY%20--%3E%20IY%5B%22NAND(y%2C%20y)%20%E5%BE%97%20%E9%9D%9Ey%22%5D%0A%20%20IX%20--%3E%20OR%5B%22%E6%88%96%EF%BC%9ANAND(%E9%9D%9Ex%2C%20%E9%9D%9Ey)%22%5D%0A%20%20IY%20--%3E%20OR%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入传输管逻辑、多米诺动态逻辑。不把功能完备与图灵完备混名：这里没有状态、没有无限带。时钟仍未出现。</p><p>后课默认：组合功能可全用 NAND 或全用 NOR 实现；CMOS 静态门是互补上拉下拉网络。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CMOS 与非/或非是互补串并联；NAND 或 NOR 单独万能。</li><li>万能是功能完备，不是延迟或面积最优。</li><li>任意布尔函数可落地为门网；代价由后课时延计量。</li><li>出处：Harris and Harris；Shannon, 1938。</li></ul>',5))])}const f=A(d,[["render",p]]);export{C as __pageData,f as default};
